{"command":"cat << 'EOF' > /tmp/test_rust/src/main.rs
use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, Command};
use log::error;
use regex::Regex;
use std::collections::HashSet;
use std::io::{BufRead, Write};
use std::path::Path;
use std::process::{exit, Command as ProcessCommand, Stdio};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RangeSpec {
    pub start: usize,
    pub end: usize,
}

pub fn parse_fields(s: &str) -> Result<Vec<RangeSpec>, String> {
    let mut specs = Vec::new();
    for part in s.split(',') {
        if part.is_empty() {
            return Err("Failed to parse field: ".to_string());
        }
        if let Some(idx) = part.find('-') {
            let low_str = &part[..idx];
            let high_str = &part[idx + 1..];
            if low_str.contains('-') || high_str.contains('-') {
                return Err(format!("Failed to parse field: {}", part));
            }
            if low_str.is_empty() && high_str.is_empty() {
                return Err("Failed to parse field: ".to_string());
            }
            let low = if low_str.is_empty() {
                1
            } else {
                match low_str.parse::<usize>() {
                    Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                    Ok(val) => val,
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            let high = if high_str.is_empty() {
                usize::MAX
            } else {
                match high_str.parse::<usize>() {
                    Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                    Ok(val) => val,
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            if high < low {
                return Err(format!("High end of range less than low end of range: {}", part));
            }
            specs.push(RangeSpec { start: low, end: high });
        } else {
            match part.parse::<usize>() {
                Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                Ok(val) => specs.push(RangeSpec { start: val, end: val }),
                Err(_) => return Err(format!("Failed to parse field: {}", part)),
            }
        }
    }
    Ok(specs)
}

fn add_range(ranges: &mut Vec<RangeSpec>, new_range: RangeSpec) {
    let x = new_range.start;
    let y = new_range.end;

    for r in ranges.iter_mut() {
        if x == r.end.saturating_add(1) {
            r.end = if r.end == usize::MAX || y == usize::MAX { usize::MAX } else { r.end.max(y) };
            return;
        }
    }
    if let Some(first) = ranges.first_mut() {
        if y.saturating_add(1) == first.start && first.start > 1 {
            first.start = first.start.min(x);
            return;
        }
    }
    ranges.push(new_range);
}

enum DelimMatcher {
    Regex(Regex),
    Literal(String),
}

impl DelimMatcher {
    fn split<'a>(&'a self, line: &'a str) -> Vec<&'a str> {
        match self {
            Self::Regex(re) => re.split(line).collect(),
            Self::Literal(lit) => {
                if lit.is_empty() {
                    vec![line]
                } else {
                    line.split(lit.as_str()).collect()
                }
            }
        }
    }
}

fn init_logger() {
    let mut builder = env_logger::Builder::new();
    builder.format(|buf, record| {
        let ts = buf.timestamp_seconds();
        writeln!(buf, "[{} {} hck] {}", ts, record.level(), record.args())
    });
    builder.filter_level(log::LevelFilter::Info);
    let _ = builder.try_init();
}

fn build_cli() -> Command {
    Command::new("executable")
        .version("git:0e2b6ba")
        .before_help("* `delimiter` is a regex by default and a fixed substring with `-L` * `header-fields` allows for specifying a literal or a regex to match header names to select columns * both `header-fields` and `fields` order dictate the order of the output columns * input files (not stdin) are automatically compressed * the output delimiter can specified with `-D`\n\n## Selection by headers\n\nInstead of specifying fields to output by index ranges (i.e `1-2,4-`), you can specify a regex or string literal to select a headered column to output with the `-F` option. By default `-F` options are treated as string literals. To treat them as regexs add the `-r` flag.\n\n## Ordering of outputs\n\n*Values are written only once*. So for a `fields` value of `4-,1,5-8`, which translates to \"print columns 4 through the end and then the last column and then columns 5 through 8\", columns 5-8 won't be printed again because they were already consumed by the `4-` range.\n\nIf `field-headers` is used as a regex then the headers will be be grouped together in groups that all matched the same regex, and in the order of the regex as specified on the CLI.")
        .arg(
            Arg::new("output")
                .short('o')
                .long("output")
                .value_name("OUTPUT")
                .help("Output file to write to, defaults to stdout"),
        )
        .arg(
            Arg::new("delimiter")
                .short('d')
                .long("delimiter")
                .value_name("DELIMITER")
                .default_value(r"\s+")
                .help("Delimiter to use on input files, this is a substring literal by default. To treat it as a literal add the `-L` flag")
                .long_help("Delimiter to use on input files, this is a substring literal by default. To treat it as a literal add the `-L` flag"),
        )
        .arg(
            Arg::new("delim-is-literal")
                .short('L')
                .long("delim-is-literal")
                .action(ArgAction::SetTrue)
                .help("Treat the delimiter as a string literal. This can significantly improve performance, especially for single byte delimiters"),
        )
        .arg(
            Arg::new("use-input-delim")
                .short('I')
                .long("use-input-delim")
                .action(ArgAction::SetTrue)
                .help("Use the input delimiter as the output delimiter if the input is literal and no other output delimiter has been set"),
        )
        .arg(
            Arg::new("output-delimiter")
                .short('D')
                .long("output-delimiter")
                .value_name("OUTPUT_DELIMITER")
                .default_value("\t")
                .help("Delimiter string to use on outputs")
                .long_help("Delimiter string to use on outputs"),
        )
        .arg(
            Arg::new("fields")
                .short('f')
                .long("fields")
                .value_name("FIELDS")
                .help("Fields to keep in the output, ex: 1,2-,-5,2-5. Fields are 1-based and inclusive"),
        )
        .arg(
            Arg::new("exclude")
                .short('e')
                .long("exclude")
                .value_name("EXCLUDE")
                .help("Fields to exclude from the output, ex: 3,9-11,15-. Exclude fields are 1 based and inclusive. Exclude fields take precedence over `fields`"),
        )
        .arg(
            Arg::new("exclude-header")
                .short('E')
                .long("exclude-header")
                .value_name("EXCLUDE_HEADER")
                .action(ArgAction::Append)
                .help("Headers to exclude from the output, ex: '^badfield.*$`. This is a string literal by default. Add the `-r` flag to treat as a regex"),
        )
        .arg(
            Arg::new("header-field")
                .short('F')
                .long("header-field")
                .value_name("HEADER_FIELD")
                .action(ArgAction::Append)
                .help("A string literal or regex to select headers, ex: '^is_.*$`. This is a string literal by default. add the `-r` flag to treat it as a regex"),
        )
        .arg(
            Arg::new("header-is-regex")
                .short('r')
                .long("header-is-regex")
                .action(ArgAction::SetTrue)
                .help("Treat the header_fields as regexs instead of string literals"),
        )
        .arg(
            Arg::new("try-decompress")
                .short('z')
                .long("try-decompress")
                .action(ArgAction::SetTrue)
                .help("Try to find the correct decompression method based on the file extensions"),
        )
        .arg(
            Arg::new("try-compress")
                .short('Z')
                .long("try-compress")
                .action(ArgAction::SetTrue)
                .help("Try to gzip compress the output"),
        )
        .arg(
            Arg::new("compression-threads")
                .short('t')
                .long("compression-threads")
                .value_name("COMPRESSION_THREADS")
                .default_value("4")
                .help("Threads to use for compression, 0 will result in `hck` staying single threaded")
                .long_help("Threads to use for compression, 0 will result in `hck` staying single threaded"),
        )
        .arg(
            Arg::new("compression-level")
                .short('l')
                .long("compression-level")
                .value_name("COMPRESSION_LEVEL")
                .default_value("6")
                .help("Compression level")
                .long_help("Compression level"),
        )
        .arg(
            Arg::new("no-mmap")
                .long("no-mmap")
                .action(ArgAction::SetTrue)
                .help("Disallow the possibility of using mmap"),
        )
        .arg(
            Arg::new("crlf")
                .long("crlf")
                .action(ArgAction::SetTrue)
                .help("Support CRLF newlines"),
        )
        .arg(
            Arg::new("input")
                .value_name("INPUT")
                .action(ArgAction::Append)
                .help("Input files to parse, defaults to stdin.")
                .long_help("Input files to parse, defaults to stdin.\n\nIf a file has a recognizable file extension indicating that it is compressed, and a local binary to perform decompression is found, decompression will occur automagically. This requires with `-z`."),
        )
}

fn open_input_reader(
    path_opt: Option<&str>,
    try_decompress: bool,
) -> Result<Box<dyn BufRead>> {
    match path_opt {
        None => {
            let stdin = std::io::stdin().lock();
            if try_decompress {
                let gz = flate2::read::GzDecoder::new(stdin);
                Ok(Box::new(std::io::BufReader::new(gz)))
            } else {
                Ok(Box::new(stdin))
            }
        }
        Some(path_str) => {
            if try_decompress {
                let p = Path::new(path_str);
                let ext = p.extension().and_then(|e| e.to_str()).unwrap_or("");
                let filename = p.file_name().and_then(|f| f.to_str()).unwrap_or("");

                let is_gz = ext == "gz" || filename.ends_with(".tgz") || filename.ends_with(".tar.gz");
                let is_bz2 = ext == "bz2" || filename.ends_with(".tbz") || filename.ends_with(".tbz2") || filename.ends_with(".tar.bz2");
                let is_xz = ext == "xz" || filename.ends_with(".txz") || filename.ends_with(".tar.xz");
                let is_zst = ext == "zst" || ext == "zstd" || filename.ends_with(".tzst") || filename.ends_with(".tar.zst");
                let is_lz4 = ext == "lz4";

                if is_gz {
                    let f = match std::fs::File::open(path_str) {
                        Ok(f) => f,
                        Err(e) => return Err(anyhow!("{}", e)),
                    };
                    let gz = flate2::read::GzDecoder::new(f);
                    return Ok(Box::new(std::io::BufReader::new(gz)));
                } else if is_bz2 || is_xz || is_zst || is_lz4 {
                    let cmd = if is_bz2 {
                        "bzip2"
                    } else if is_xz {
                        "xz"
                    } else if is_zst {
                        "zstd"
                    } else {
                        "lz4"
                    };
                    let child = ProcessCommand::new(cmd)
                        .args(&["-dc", path_str])
                        .stdout(Stdio::piped())
                        .stderr(Stdio::piped())
                        .spawn();
                    match child {
                        Ok(mut c) => {
                            let stdout = c.stdout.take().unwrap();
                            let stderr = c.stderr.take().unwrap();
                            std::thread::spawn(move || {
                                use std::io::Read;
                                let mut err_buf = String::new();
                                let mut stderr = stderr;
                                let _ = stderr.read_to_string(&mut err_buf);
                                if !err_buf.trim().is_empty() {
                                    error!("\n    -------------------------------------------------------------------------------\n    {}\n    -------------------------------------------------------------------------------", err_buf.trim());
                                }
                            });
                            return Ok(Box::new(std::io::BufReader::new(stdout)));
                        }
                        Err(e) => return Err(anyhow!("{}", e)),
                    }
                }
            }
            let f = match std::fs::File::open(path_str) {
                Ok(f) => f,
                Err(e) => return Err(anyhow!("{}", e)),
            };
            Ok(Box::new(std::io::BufReader::new(f)))
        }
    }
}

fn open_output_writer(
    path_opt: Option<&str>,
    try_compress: bool,
    level: u32,
) -> Result<Box<dyn Write>> {
    let base_writer: Box<dyn Write> = match path_opt {
        None => Box::new(std::io::BufWriter::new(std::io::stdout().lock())),
        Some(p) => Box::new(std::io::BufWriter::new(std::fs::File::create(p)?)),
    };
    if try_compress {
        let encoder = flate2::write::GzEncoder::new(
            base_writer,
            flate2::Compression::new(level.min(9)),
        );
        Ok(Box::new(encoder))
    } else {
        Ok(base_writer)
    }
}

fn main() {
    init_logger();

    let matches = build_cli().get_matches();

    let delim_str = matches.get_one::<String>("delimiter").map(|s| s.as_str()).unwrap_or(r"\s+");
    let delim_is_literal = matches.get_flag("delim-is-literal");
    let use_input_delim = matches.get_flag("use-input-delim");
    let output_delim_arg = matches.get_one::<String>("output-delimiter").map(|s| s.as_str()).unwrap_or("\t");

    let output_delim = if use_input_delim && delim_is_literal {
        delim_str
    } else {
        output_delim_arg
    };

    let matcher = if delim_is_literal {
        DelimMatcher::Literal(delim_str.to_string())
    } else {
        match Regex::new(delim_str) {
            Ok(re) => DelimMatcher::Regex(re),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        }
    };

    let field_specs = if let Some(fields_str) = matches.get_one::<String>("fields") {
        match parse_fields(fields_str) {
            Ok(s) => Some(s),
            Err(e) => {
                error!("{}", e);
                exit(1);
            }
        }
    } else {
        None
    };

    let exclude_specs = if let Some(exclude_str) = matches.get_one::<String>("exclude") {
        match parse_fields(exclude_str) {
            Ok(s) => Some(s),
            Err(e) => {
                error!("{}", e);
                exit(1);
            }
        }
    } else {
        None
    };

    let header_fields: Vec<String> = matches
        .get_many::<String>("header-field")
        .unwrap_or_default()
        .cloned()
        .collect();

    let exclude_headers: Vec<String> = matches
        .get_many::<String>("exclude-header")
        .unwrap_or_default()
        .cloned()
        .collect();

    let header_is_regex = matches.get_flag("header-is-regex");
    let try_decompress = matches.get_flag("try-decompress");
    let try_compress = matches.get_flag("try-compress");
    let crlf = matches.get_flag("crlf");

    let compression_level: u32 = matches
        .get_one::<String>("compression-level")
        .and_then(|s| s.parse().ok())
        .unwrap_or(6);

    let output_path = matches.get_one::<String>("output").map(|s| s.as_str());

    let mut writer = match open_output_writer(output_path, try_compress, compression_level) {
        Ok(w) => w,
        Err(e) => {
            error!("{}", e);
            exit(1);
        }
    };

    let record_sep = if crlf { "\r\n" } else { "\n" };

    let input_files: Vec<String> = matches
        .get_many::<String>("input")
        .unwrap_or_default()
        .cloned()
        .collect();

    let inputs: Vec<Option<String>> = if input_files.is_empty() {
        vec![None]
    } else {
        input_files.into_iter().map(Some).collect()
    };

    let active_header_mode = !header_fields.is_empty() || !exclude_headers.is_empty();

    for input_opt in inputs {
        let mut reader = match open_input_reader(input_opt.as_deref(), try_decompress) {
            Ok(r) => r,
            Err(e) => {
                error!("{}", e);
                exit(1);
            }
        };

        let mut line_buf = String::new();
        let mut is_first_line = true;

        let mut ranges: Vec<RangeSpec> = Vec::new();
        let mut excluded_indices: HashSet<usize> = HashSet::new();

        if let Some(ref ex) = exclude_specs {
            for spec in ex {
                let high = spec.end;
                for i in spec.start..=high {
                    excluded_indices.insert(i);
                    if high == usize::MAX {
                        break;
                    }
                }
            }
        }

        loop {
            line_buf.clear();
            match reader.read_line(&mut line_buf) {
                Ok(0) => {
                    if is_first_line && active_header_mode {
                        error!("No headers matched");
                        exit(1);
                    }
                    break;
                }
                Ok(_) => {}
                Err(e) => {
                    error!("{}", e);
                    exit(1);
                }
            }

            let mut trimmed = line_buf.as_str();
            if trimmed.ends_with('\n') {
                trimmed = &trimmed[..trimmed.len() - 1];
            }
            if trimmed.ends_with('\r') {
                trimmed = &trimmed[..trimmed.len() - 1];
            }

            let fields = matcher.split(trimmed);
            let n_fields = fields.len();

            if is_first_line {
                is_first_line = false;

                if active_header_mode {
                    // Match exclude headers
                    for (i, &h) in fields.iter().enumerate() {
                        let idx = i + 1;
                        for ex_p in &exclude_headers {
                            let matched = if header_is_regex {
                                match Regex::new(ex_p) {
                                    Ok(re) => re.is_match(h),
                                    Err(e) => {
                                        eprintln!("Error: {}", e);
                                        exit(1);
                                    }
                                }
                            } else {
                                h == ex_p.as_str()
                            };
                            if matched {
                                excluded_indices.insert(idx);
                            }
                        }
                    }

                    // Match header fields
                    if !header_fields.is_empty() {
                        let mut total_matches = 0;
                        for h_p in &header_fields {
                            let mut p_matches = Vec::new();
                            for (i, &h) in fields.iter().enumerate() {
                                let idx = i + 1;
                                let matched = if header_is_regex {
                                    match Regex::new(h_p) {
                                        Ok(re) => re.is_match(h),
                                        Err(e) => {
                                            eprintln!("Error: {}", e);
                                            exit(1);
                                        }
                                    }
                                } else {
                                    h == h_p.as_str()
                                };
                                if matched {
