                match high_str.parse::<usize>() {
                    Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                    Ok(val) => val,
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            if high < low {
                return Err(format!("High end of range less than low end of range: {}", part));
            }
            specs.push(RangeSpec { start: low, end: high });
        } else {
            match part.parse::<usize>() {
                Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                Ok(val) => specs.push(RangeSpec { start: val, end: val }),
                Err(_) => return Err(format!("Failed to parse field: {}", part)),
            }
        }
    }
    Ok(specs)
}

fn add_range(ranges: &mut Vec<RangeSpec>, new_range: RangeSpec) {
    let x = new_range.start;
    let y = new_range.end;

    for r in ranges.iter_mut() {
        if x == r.end.saturating_add(1) {
            r.end = if r.end == usize::MAX || y == usize::MAX { usize::MAX } else { r.end.max(y) };
            return;
        }
    }
    if let Some(first) = ranges.first_mut() {
        if y.saturating_add(1) == first.start && first.start > 1 {
            first.start = first.start.min(x);
            return;
        }
    }
    ranges.push(new_range);
}

enum DelimMatcher {
    Regex(Regex),
    Literal(String),
}

impl DelimMatcher {
    fn split<'a>(&'a self, line: &'a str) -> Vec<&'a str> {
        match self {
            Self::Regex(re) => re.split(line).collect(),
            Self::Literal(lit) => {
                if lit.is_empty() {
                    vec![line]
                } else {
                    line.split(lit.as_str()).collect()
                }
            }
        }
    }
}

