#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RangeSpec {
    pub start: usize,
    pub end: usize,
}

pub fn parse_fields(s: &str) -> Result<Vec<RangeSpec>, String> {
    let mut specs = Vec::new();
    for part in s.split(',') {
        if part.is_empty() {
            return Err("Failed to parse field: ".to_string());
        }
        if let Some(idx) = part.find('-') {
            let low_str = &part[..idx];
            let high_str = &part[idx + 1..];
            if low_str.contains('-') || high_str.contains('-') {
                return Err(format!("Failed to parse field: {}", part));
            }
            if low_str.is_empty() && high_str.is_empty() {
                return Err("Failed to parse field: ".to_string());
            }
            let low = if low_str.is_empty() {
                1
            } else {
                match low_str.parse::<usize>() {
                    Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                    Ok(val) => val,
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            let high = if high_str.is_empty() {
                usize::MAX
            } else {
                match high_str.parse::<usize>() {
                    Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                    Ok(val) => val,
                    Err(_) => return Err(format!("Failed to parse field: {}", part)),
                }
            };
            if high < low {
                return Err(format!("High end of range less than low end of range: {}", part));
            }
            specs.push(RangeSpec { start: low, end: high });
        } else {
            match part.parse::<usize>() {
                Ok(0) => return Err("Fields and positions are numbered from 1: 0".to_string()),
                Ok(val) => specs.push(RangeSpec { start: val, end: val }),
                Err(_) => return Err(format!("Failed to parse field: {}", part)),
            }
        }
    }
    Ok(specs)
}

fn insert_header_index(ranges: &mut Vec<RangeSpec>, h: usize) {
    if ranges.is_empty() {
        ranges.push(RangeSpec { start: h, end: h });
        return;
    }

    for r in ranges.iter() {
        if h >= r.start && h <= r.end {
            return;
        }
    }

    for r in ranges.iter_mut() {
        if h == r.end.saturating_add(1) {
            r.end = h;
            return;
        }
        if h + 1 == r.start {
            r.start = h;
            return;
        }
    }

    let mut insert_idx = ranges.len();
    for (i, r) in ranges.iter().enumerate() {
        if h < r.start {
            insert_idx = i;
            break;
        }
    }
    ranges.insert(insert_idx, RangeSpec { start: h, end: h });
}

enum DelimMatcher {
    Regex(Regex),
    Literal(String),
}

impl DelimMatcher {
    fn split<'a>(&'a self, line: &'a str) -> Vec<&'a str> {
        match self {
            Self::Regex(re) => re.split(line).collect(),
            Self::Literal(lit) => {
                if lit.is_empty() {
                    vec![line]
                } else {
                    line.split(lit.as_str()).collect()
                }
            }
        }
    }
}

fn init_logger() {
    let mut builder = env_logger::Builder::new();
    builder.format(|buf, record| {
        let ts = buf.timestamp_seconds();
        writeln!(buf, "[{} {} hck] {}", ts, record.level(), record.args())
    });
    builder.filter_level(log::LevelFilter::Info);
    let _ = builder.try_init();
}

