fn open_input_reader(
    path_opt: Option<&str>,
    try_decompress: bool,
) -> Result<Box<dyn BufRead>> {
    match path_opt {
        None => {
            let stdin = std::io::stdin().lock();
            if try_decompress {
                let gz = flate2::read::GzDecoder::new(stdin);
                Ok(Box::new(std::io::BufReader::new(gz)))
            } else {
                Ok(Box::new(stdin))
            }
        }
        Some(path_str) => {
            if try_decompress {
                let p = Path::new(path_str);
                let ext = p.extension().and_then(|e| e.to_str()).unwrap_or("");
                let filename = p.file_name().and_then(|f| f.to_str()).unwrap_or("");

                let is_gz = ext == "gz" || filename.ends_with(".tgz") || filename.ends_with(".tar.gz");
                let is_bz2 = ext == "bz2" || filename.ends_with(".tbz") || filename.ends_with(".tbz2") || filename.ends_with(".tar.bz2");
                let is_xz = ext == "xz" || filename.ends_with(".txz") || filename.ends_with(".tar.xz");
                let is_zst = ext == "zst" || ext == "zstd" || filename.ends_with(".tzst") || filename.ends_with(".tar.zst");
                let is_lz4 = ext == "lz4";

                if is_gz {
                    let f = match std::fs::File::open(path_str) {
                        Ok(f) => f,
                        Err(e) => return Err(anyhow!("{}", e)),
                    };
                    let gz = flate2::read::GzDecoder::new(f);
                    return Ok(Box::new(std::io::BufReader::new(gz)));
                } else if is_bz2 || is_xz || is_zst || is_lz4 {
                    let cmd = if is_bz2 {
                        "bzip2"
                    } else if is_xz {
                        "xz"
                    } else if is_zst {
                        "zstd"
                    } else {
                        "lz4"
                    };
                    let child = ProcessCommand::new(cmd)
                        .args(&["-dc", path_str])
                        .stdout(Stdio::piped())
                        .stderr(Stdio::piped())
                        .spawn();
                    match child {
                        Ok(mut c) => {
                            let stdout = c.stdout.take().unwrap();
                            let stderr = c.stderr.take().unwrap();
                            std::thread::spawn(move || {
                                use std::io::Read;
                                let mut err_buf = String::new();
                                let mut stderr = stderr;
                                let _ = stderr.read_to_string(&mut err_buf);
                                if !err_buf.trim().is_empty() {
                                    error!("\n    -------------------------------------------------------------------------------\n    {}\n    -------------------------------------------------------------------------------", err_buf.trim());
                                }
                            });
                            return Ok(Box::new(std::io::BufReader::new(stdout)));
                        }
                        Err(e) => return Err(anyhow!("{}", e)),
                    }
                }
            }
            let f = match std::fs::File::open(path_str) {
                Ok(f) => f,
                Err(e) => return Err(anyhow!("{}", e)),
            };
            Ok(Box::new(std::io::BufReader::new(f)))
        }
    }
}

fn open_output_writer(
    path_opt: Option<&str>,
    try_compress: bool,
    level: u32,
) -> Result<Box<dyn Write>> {
    let base_writer: Box<dyn Write> = match path_opt {
        None => Box::new(std::io::BufWriter::new(std::io::stdout().lock())),
        Some(p) => Box::new(std::io::BufWriter::new(std::fs::File::create(p)?)),
    };
    if try_compress {
        let encoder = flate2::write::GzEncoder::new(
            base_writer,
            flate2::Compression::new(level.min(9)),
        );
        Ok(Box::new(encoder))
    } else {
        Ok(base_writer)
    }
}

