                .value_name("INPUT")
                .action(ArgAction::Append)
                .help("Input files to parse, defaults to stdin.")
                .long_help("Input files to parse, defaults to stdin.\n\nIf a file has a recognizable file extension indicating that it is compressed, and a local binary to perform decompression is found, decompression will occur automagically. This requires with `-z`."),
        )
}

fn open_input_reader(
    path_opt: Option<&str>,
    try_decompress: bool,
) -> Result<Box<dyn BufRead>> {
    match path_opt {
        None => {
            let stdin = std::io::stdin().lock();
            if try_decompress {
                let gz = flate2::read::GzDecoder::new(stdin);
                Ok(Box::new(std::io::BufReader::new(gz)))
            } else {
                Ok(Box::new(stdin))
            }
        }
        Some(path_str) => {
            if try_decompress {
                let p = Path::new(path_str);
                let ext = p.extension().and_then(|e| e.to_str()).unwrap_or("");
                let filename = p.file_name().and_then(|f| f.to_str()).unwrap_or("");

                let is_gz = ext == "gz" || filename.ends_with(".tgz") || filename.ends_with(".tar.gz");
                let is_bz2 = ext == "bz2" || filename.ends_with(".tbz") || filename.ends_with(".tbz2") || filename.ends_with(".tar.bz2");
                let is_xz = ext == "xz" || filename.ends_with(".txz") || filename.ends_with(".tar.xz");
                let is_zst = ext == "zst" || ext == "zstd" || filename.ends_with(".tzst") || filename.ends_with(".tar.zst");
                let is_lz4 = ext == "lz4";

                if is_gz {
                    let f = match std::fs::File::open(path_str) {
                        Ok(f) => f,
                        Err(e) => return Err(anyhow!("{}", e)),
                    };
                    let gz = flate2::read::GzDecoder::new(f);
                    return Ok(Box::new(std::io::BufReader::new(gz)));
                } else if is_bz2 || is_xz || is_zst || is_lz4 {
                    let cmd = if is_bz2 {
                        "bzip2"
                    } else if is_xz {
                        "xz"
                    } else if is_zst {
                        "zstd"
                    } else {
                        "lz4"
                    };
                    let child = ProcessCommand::new(cmd)
                        .args(&["-dc", path_str])
                        .stdout(Stdio::piped())
                        .stderr(Stdio::piped())
                        .spawn();
                    match child {
                        Ok(mut c) => {
                            let stdout = c.stdout.take().unwrap();
                            let stderr = c.stderr.take().unwrap();
                            std::thread::spawn(move || {
                                use std::io::Read;
                                let mut err_buf = String::new();
                                let mut stderr = stderr;
                                let _ = stderr.read_to_string(&mut err_buf);
                                if !err_buf.trim().is_empty() {
                                    error!("\n    -------------------------------------------------------------------------------\n    {}\n    -------------------------------------------------------------------------------", err_buf.trim());
                                }
                            });
                            return Ok(Box::new(std::io::BufReader::new(stdout)));
                        }
                        Err(e) => return Err(anyhow!("{}", e)),
                    }
                }
            }
            let f = match std::fs::File::open(path_str) {
                Ok(f) => f,
                Err(e) => return Err(anyhow!("{}", e)),
            };
            Ok(Box::new(std::io::BufReader::new(f)))
        }
    }
}

fn open_output_writer(
    path_opt: Option<&str>,
    try_compress: bool,
    level: u32,
) -> Result<Box<dyn Write>> {
    let base_writer: Box<dyn Write> = match path_opt {
        None => Box::new(std::io::BufWriter::new(std::io::stdout().lock())),
        Some(p) => Box::new(std::io::BufWriter::new(std::fs::File::create(p)?)),
    };
    if try_compress {
        let encoder = flate2::write::GzEncoder::new(
            base_writer,
            flate2::Compression::new(level.min(9)),
        );
        Ok(Box::new(encoder))
    } else {
        Ok(base_writer)
    }
}

fn main() {
    init_logger();

    let matches = build_cli().get_matches();

    let delim_str = matches.get_one::<String>("delimiter").map(|s| s.as_str()).unwrap_or(r"\s+");
    let delim_is_literal = matches.get_flag("delim-is-literal");
    let use_input_delim = matches.get_flag("use-input-delim");
    let output_delim_arg = matches.get_one::<String>("output-delimiter").map(|s| s.as_str()).unwrap_or("\t");

    let output_delim = if use_input_delim && delim_is_literal {
        delim_str
    } else {
        output_delim_arg
    };

    let matcher = if delim_is_literal {
        DelimMatcher::Literal(delim_str.to_string())
    } else {
        match Regex::new(delim_str) {
            Ok(re) => DelimMatcher::Regex(re),
            Err(e) => {
                eprintln!("Error: {}", e);
                exit(1);
            }
        }
    };

    let field_specs = if let Some(fields_str) = matches.get_one::<String>("fields") {
        match parse_fields(fields_str) {
            Ok(s) => Some(s),
            Err(e) => {
                error!("{}", e);
                exit(1);
            }
        }
    } else {
        None
    };

    let exclude_specs = if let Some(exclude_str) = matches.get_one::<String>("exclude") {
        match parse_fields(exclude_str) {
            Ok(s) => Some(s),
            Err(e) => {
                error!("{}", e);
                exit(1);
            }
        }
    } else {
        None
    };

    let header_fields: Vec<String> = matches
        .get_many::<String>("header-field")
        .unwrap_or_default()
        .cloned()
        .collect();

    let exclude_headers: Vec<String> = matches
        .get_many::<String>("exclude-header")
        .unwrap_or_default()
        .cloned()
        .collect();

    let header_is_regex = matches.get_flag("header-is-regex");
    let try_decompress = matches.get_flag("try-decompress");
    let try_compress = matches.get_flag("try-compress");
    let crlf = matches.get_flag("crlf");

    let compression_level: u32 = matches
        .get_one::<String>("compression-level")
        .and_then(|s| s.parse().ok())
        .unwrap_or(6);

    let output_path = matches.get_one::<String>("output").map(|s| s.as_str());

    let mut writer = match open_output_writer(output_path, try_compress, compression_level) {
        Ok(w) => w,
        Err(e) => {
            error!("{}", e);
            exit(1);
        }
    };

    let record_sep = if crlf { "\r\n" } else { "\n" };

    let input_files: Vec<String> = matches
        .get_many::<String>("input")
        .unwrap_or_default()
        .cloned()
        .collect();

    let inputs: Vec<Option<String>> = if input_files.is_empty() {
        vec![None]
    } else {
        input_files.into_iter().map(Some).collect()
    };

    let active_header_mode = !header_fields.is_empty() || !exclude_headers.is_empty();

    for input_opt in inputs {
        let mut reader = match open_input_reader(input_opt.as_deref(), try_decompress) {
            Ok(r) => r,
            Err(e) => {
                error!("{}", e);
                exit(1);
            }
        };

        let mut line_buf = String::new();
        let mut is_first_line = true;

        let mut ranges: Vec<RangeSpec> = Vec::new();
        let mut excluded_indices: HashSet<usize> = HashSet::new();

        if let Some(ref ex) = exclude_specs {
            for spec in ex {
                let high = spec.end;
                for i in spec.start..=high {
                    excluded_indices.insert(i);
                    if high == usize::MAX {
                        break;
                    }
                }
            }
        }

        loop {
            line_buf.clear();
            match reader.read_line(&mut line_buf) {
                Ok(0) => {
                    if is_first_line && active_header_mode {
                        error!("No headers matched");
                        exit(1);
                    }
                    break;
                }
                Ok(_) => {}
                Err(e) => {
                    error!("{}", e);
                    exit(1);
                }
            }

            let mut trimmed = line_buf.as_str();
            if trimmed.ends_with('\n') {
                trimmed = &trimmed[..trimmed.len() - 1];
            }
            if trimmed.ends_with('\r') {
                trimmed = &trimmed[..trimmed.len() - 1];
            }

            let fields = matcher.split(trimmed);
            let n_fields = fields.len();

            if is_first_line {
                is_first_line = false;

                if active_header_mode {
                    // Match exclude headers
                    for (i, &h) in fields.iter().enumerate() {
                        let idx = i + 1;
                        for ex_p in &exclude_headers {
                            let matched = if header_is_regex {
                                match Regex::new(ex_p) {
                                    Ok(re) => re.is_match(h),
                                    Err(e) => {
                                        eprintln!("Error: {}", e);
                                        exit(1);
                                    }
                                }
                            } else {
                                h == ex_p.as_str()
                            };
                            if matched {
                                excluded_indices.insert(idx);
                            }
                        }
                    }

                    let mut matched_headers = Vec::new();
                    if !header_fields.is_empty() {
                        let mut total_matches = 0;
                        for h_p in &header_fields {
                            let mut p_matches = Vec::new();
                            for (i, &h) in fields.iter().enumerate() {
                                let idx = i + 1;
                                let matched = if header_is_regex {
                                    match Regex::new(h_p) {
                                        Ok(re) => re.is_match(h),
                                        Err(e) => {
                                            eprintln!("Error: {}", e);
                                            exit(1);
                                        }
                                    }
                                } else {
                                    h == h_p.as_str()
                                };
                                if matched {
                                    p_matches.push(idx);
                                }
                            }
                            if p_matches.is_empty() {
                                if total_matches == 0 {
                                    // Check if any match at all
                                } else {
                                    error!("Header not found: {}", h_p);
                                    exit(1);
                                }
                            } else {
                                total_matches += p_matches.len();
                                matched_headers.extend(p_matches);
                            }
                        }

                        if total_matches == 0 {
                            error!("No headers matched");
                            exit(1);
                        }
                    }

                    if let Some(ref f_specs) = field_specs {
                        ranges = f_specs.clone();
                        for m in matched_headers {
                            insert_header_into_specs(&mut ranges, m);
                        }
                    } else {
                        for m in matched_headers {
                            ranges.push(RangeSpec { start: m, end: m });
                        }
                    }
                } else if let Some(ref f_specs) = field_specs {
                    ranges = f_specs.clone();
                } else {
                    ranges.push(RangeSpec { start: 1, end: usize::MAX });
                }
            }

            let mut seen: HashSet<usize> = HashSet::new();
            let mut first = true;

            for r in &ranges {
                let high = if r.end == usize::MAX { n_fields } else { r.end.min(n_fields) };
                for i in r.start..=high {
                    if i <= n_fields && !seen.contains(&i) && !excluded_indices.contains(&i) {
                        seen.insert(i);
                        if !first {
                            if let Err(e) = writer.write_all(output_delim.as_bytes()) {
                                if e.kind() == std::io::ErrorKind::BrokenPipe {
                                    exit(0);
                                }
                                exit(1);
                            }
                        }
                        if let Err(e) = writer.write_all(fields[i - 1].as_bytes()) {
                            if e.kind() == std::io::ErrorKind::BrokenPipe {
                                exit(0);
                            }
                            exit(1);
                        }
                        first = false;
                    }
                }
            }

            if let Err(e) = writer.write_all(record_sep.as_bytes()) {
                if e.kind() == std::io::ErrorKind::BrokenPipe {
                    exit(0);
                }
                exit(1);
            }
        }
    }

    let _ = writer.flush();
}
