                .default_value(r"\s+")
                .help("Delimiter to use on input files, this is a substring literal by default. To treat it as a literal add the `-L` flag")
                .long_help("Delimiter to use on input files, this is a substring literal by default. To treat it as a literal add the `-L` flag"),
        )
        .arg(
            Arg::new("delim-is-literal")
                .short('L')
                .long("delim-is-literal")
                .action(ArgAction::SetTrue)
                .help("Treat the delimiter as a string literal. This can significantly improve performance, especially for single byte delimiters"),
        )
        .arg(
            Arg::new("use-input-delim")
                .short('I')
                .long("use-input-delim")
                .action(ArgAction::SetTrue)
                .help("Use the input delimiter as the output delimiter if the input is literal and no other output delimiter has been set"),
        )
        .arg(
            Arg::new("output-delimiter")
                .short('D')
                .long("output-delimiter")
                .value_name("OUTPUT_DELIMITER")
